/*
 * ТЭПСИС · котельная, ч/б фото (kotelnaya-bw.js)
 * Вставка в Tilda (блок T123 или HTML-элемент Zero Block):
 *   <div class="tps-wave-bw"></div>
 *   <script src="https://cdn.jsdelivr.net/gh/vesnins/tepsys@ТЕГ/kotelnaya-bw.js"></script>
 * Необязательные атрибуты у div: data-color="#0020C3", data-ratio="1.5" (ширина/высота картинки)
 */
(function(){
  if (window.__tpsWaveBwLoaded) return; window.__tpsWaveBwLoaded = true;
  var css = ".tps-wave-bw{position:relative;width:100%;aspect-ratio:3/2;overflow:hidden;cursor:default;-webkit-tap-highlight-color:transparent} @supports not (aspect-ratio:1/1){.tps-wave-bw{height:0;padding-bottom:66.6667%}} .tps-wave-bw canvas{position:absolute;inset:0;width:100%;height:100%;display:block}";
  var st = document.createElement('style'); st.textContent = css;
  (document.head||document.documentElement).appendChild(st);

  /* ===== Настройки ===== */
  var CELL  = 3;     // ширина одного «символа» (период волны), px — не масштабируется
  var ROW   = 4;     // шаг строк, px
  var LINE  = 0.8;   // толщина линии, px
  var AMIN  = 0.18;  // высота волны в самых светлых местах, px
  var AMAX  = 2.5;   // высота волны в самых тёмных местах, px
  var LEVELS = 9;    // сколько разных «символов» (градаций высоты)
  var GAMMA = 2.0;   // >1 — светлее полутона, <1 — темнее
  var TINT  = 0.08;  // плотность бледной заливки фона (0 — без заливки)
  var BAND  = 0.35;  // мягкость края при проявлении сверху вниз (доля высоты)
  var LOAD_MS = 2200;
  /* «Дыхание» — символы понемногу сменяются после загрузки */
  var BREATH_DELAY = 1000; // пауза после загрузки, мс
  var BREATH_IN    = 1500; // плавный разгон эффекта, мс
  var BREATH_AMP   = 1.0;  // на сколько ступеней может сдвинуться символ (1 = на соседний)
  var BREATH_SPEED = 0.35; // скорость «волн» дыхания
  var FLICKER      = 1.2;  // как часто отдельные символы меняются сами по себе (раз/сек)
  var FLIP         = 0.15; // доля символов, которые иногда зеркалятся (0…1)
  var BREATHE      = false; // «дыхание» выключено
  var FPS          = 30;   // частота кадров анимации
  var IMG = "data:image/jpeg;base64,";

  function scan(){
    var roots = document.querySelectorAll('.tps-wave-bw:not([data-ready])');
    for (var i=0;i<roots.length;i++){ try{ init(roots[i]); }catch(e){ roots[i].insertAdjacentHTML('beforeend','<div style="position:absolute;left:8px;top:8px;font:13px Arial;color:#c00">Ошибка картинки: '+e.message+'</div>'); } }
  }
  scan();
  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',scan);
  window.addEventListener('load',scan);
  setTimeout(scan,500); setTimeout(scan,1500); setTimeout(scan,3000);

  /* Zero Block: растягиваем на размер HTML-элемента, заданный в редакторе */
  function fitZero(root){
    var el = root.closest ? root.closest('.tn-elem') : null;
    if (!el) return;
    root.style.aspectRatio='auto'; root.style.paddingBottom='0';
    root.style.height='100%';
    var p=root.parentNode;
    while(p && p!==el){ p.style.height='100%'; p.style.width='100%'; p=p.parentNode; }
  }

  function hex(c){c=c.replace('#','');return [parseInt(c.substr(0,2),16)/255,parseInt(c.substr(2,2),16)/255,parseInt(c.substr(4,2),16)/255];}

  function init(root){
    root.setAttribute('data-ready','1');
    fitZero(root);
    var canvas = root.querySelector('canvas');
    if(!canvas){ canvas=document.createElement('canvas'); root.appendChild(canvas); }
    var color = hex(root.getAttribute('data-color')||'#0020C3');
    var ratio = parseFloat(root.getAttribute('data-ratio')||'1.5');
    var img = new Image();
    var st = {prog:0, breath:0, tEnd:0, visible:true, started:false, t0:0, raf:0, w:0, h:0, dpr:1};
    var gl = canvas.getContext('webgl',{premultipliedAlpha:true,antialias:false}) || canvas.getContext('experimental-webgl');
    var R = null;
    try { R = gl ? glRenderer(gl) : null; } catch(e){ R = null; }
    if (!R){ var nc=document.createElement('canvas'); root.replaceChild(nc,canvas); canvas=nc; }
    var ctx = R ? null : canvas.getContext('2d');
    var lumaData = null;

    img.onload = function(){
      if (R) { try { R.setImage(img); } catch(e){ console.warn('tps-wave-bw',e); } }
      if (!R) {
        var c=document.createElement('canvas');c.width=img.width;c.height=img.height;
        var x=c.getContext('2d');x.drawImage(img,0,0);
        var d=x.getImageData(0,0,c.width,c.height).data, L=new Float32Array(c.width*c.height);
        for(var k=0;k<L.length;k++)L[k]=d[k*4]/255;
        lumaData={w:c.width,h:c.height,L:L};
      }
      resize(); observe();
    };
    img.onerror=function(){ root.insertAdjacentHTML('beforeend','<div style="position:absolute;left:8px;top:8px;font:13px Arial;color:#c00">Картинка не загрузилась — код вставлен не полностью?</div>'); };
    img.src = IMG;

    function resize(){
      var r=root.getBoundingClientRect();
      st.dpr=Math.min(window.devicePixelRatio||1,2);
      st.w=r.width; st.h=r.height;
      if (r.width<2 || r.height<2){ setTimeout(resize,300); return; }
      canvas.width=Math.max(1,Math.round(r.width*st.dpr));
      canvas.height=Math.max(1,Math.round(r.height*st.dpr));
      draw();
    }
    if (window.ResizeObserver) new ResizeObserver(function(){resize();}).observe(root);
    else window.addEventListener('resize',resize);

    function observe(){
      if (!('IntersectionObserver' in window)) return start();
      var io=new IntersectionObserver(function(e){ if(e[0].isIntersecting){io.disconnect();start();} },{threshold:0.2});
      io.observe(root);
    }
    function start(){ if(st.started)return; st.started=true; st.t0=performance.now(); loop(); }

    var still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var breathe = BREATHE && !!R && !still;
    if ('IntersectionObserver' in window) new IntersectionObserver(function(e){ st.visible=e[0].isIntersecting; if(st.visible) loop(); }).observe(root);
    document.addEventListener('visibilitychange',function(){ if(!document.hidden) loop(); });

    var lastDraw=0, T0=performance.now();
    function loop(){ if(!st.raf) st.raf=requestAnimationFrame(tick); }
    function tick(now){
      st.raf=0;
      var loading = st.started && st.prog<1;
      if(st.started) st.prog=Math.min(1,(now-st.t0)/LOAD_MS);
      if(st.prog>=1 && !st.tEnd) st.tEnd=now;
      if(breathe && st.tEnd){ var b=(now-st.tEnd-BREATH_DELAY)/BREATH_IN; st.breath=Math.max(0,Math.min(1,b)); st.breath=st.breath*st.breath*(3-2*st.breath); }
      var animating = breathe && st.tEnd && st.visible && !document.hidden;
      if(loading || !animating || now-lastDraw >= 1000/FPS - 2){ lastDraw=now; st.time=(now-T0)/1000; draw(); }
      if(loading || animating || (st.started&&!st.tEnd)) loop();
    }

    function draw(){
      if(!st.w) return;
      var p=st.prog;
      if(R) R.draw(canvas.width,canvas.height,st.dpr,p,st.breath,st.time||0,color,ratio);
      else if(lumaData) draw2d(p);
    }

    /* ---------- WebGL ---------- */
    function glRenderer(gl){
      var vs='attribute vec2 a;void main(){gl_Position=vec4(a,0.,1.);}';
      var fs=[
        'precision highp float;',
        'uniform sampler2D T;uniform vec2 S;uniform float D,P,B,TM,IR;uniform vec3 C;',
        'const float TINT='+TINT.toFixed(3)+',BAND='+BAND.toFixed(3)+',CELL='+CELL.toFixed(3)+',ROW='+ROW.toFixed(3)+',LW='+LINE.toFixed(3)+',AMIN='+AMIN.toFixed(3)+',AMAX='+AMAX.toFixed(3)+',LV='+LEVELS.toFixed(1)+';',
        'float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}',
        'float rev(float y){float f=(P-.12)/.88*(1.+BAND);return clamp((f-y/S.y)/BAND,0.,1.);}',
        'float h3(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}',
        'float vn(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);',
        ' return mix(mix(mix(h3(i),h3(i+vec3(1,0,0)),f.x),mix(h3(i+vec3(0,1,0)),h3(i+vec3(1,1,0)),f.x),f.y),',
        '            mix(mix(h3(i+vec3(0,0,1)),h3(i+vec3(1,0,1)),f.x),mix(h3(i+vec3(0,1,1)),h3(i+vec3(1,1,1)),f.x),f.y),f.z);}',
        'vec2 cover(vec2 q){float ar=S.x/S.y;vec2 uv=q/S;',
        ' if(ar>IR){float k=IR/ar;uv.y=(uv.y-.5)*k+.5;}else{float k=ar/IR;uv.x=(uv.x-.5)*k+.5;}return uv;}',
        'float amp(float cx,float cy){',
        ' float d=pow(1.-texture2D(T,cover(vec2(cx,cy))).r,'+GAMMA.toFixed(3)+');',
        ' vec2 cl=vec2(floor(cx/CELL),floor(cy/ROW));',
        ' float n=hash(cl);',
        ' float rv=smoothstep(0.,.7,rev(cy)*1.4-(1.-d)*.4-n*.1);',
        ' d*=rv;',
        ' float sg=1.;',
        ' if(B>0.){',
        '  float live=smoothstep(.03,.2,d);',
        '  float wv=vn(vec3(cl.x*.07,cl.y*.11,TM*'+BREATH_SPEED.toFixed(3)+'))-.5;',
        '  float fl=hash(cl+floor(TM*'+FLICKER.toFixed(3)+'+n*17.))-.5;',
        '  d+=B*live*(wv*1.4+fl*.9)*'+BREATH_AMP.toFixed(3)+'/LV;',
        '  if(hash(cl.yx+floor(TM*.6+n*9.))<B*live*'+FLIP.toFixed(3)+') sg=-1.;',
        ' }',
        ' d=floor(clamp(d,0.,1.)*LV+.5)/LV;',
        ' return sg*(AMIN+(AMAX-AMIN)*d);}',
        'void main(){',
        ' vec2 q=vec2(gl_FragCoord.x,S.y*D-gl_FragCoord.y)/D;',
        ' float row=floor(q.y/ROW);',
        ' float cx=(floor(q.x/CELL)+.5)*CELL;',
        ' float w=6.28318530718/CELL; float s=sin(q.x*w), c=cos(q.x*w);',
        ' float aa=.75/D, a=0.;',
        ' for(int i=-1;i<=1;i++){',
        '  float cy=(row+float(i)+.5)*ROW;',
        '  float A=amp(cx,cy);',
        '  float y0=cy+A*s; float sl=A*w*c;',
        '  float dist=abs(q.y-y0)/sqrt(1.+sl*sl);',
        '  a=max(a,1.-smoothstep(LW*.5-aa,LW*.5+aa,dist));',
        ' }',
        ' float tin=smoothstep(0.,.12,P);',
        ' a*=tin*mix(.3,1.,smoothstep(0.,.6,rev(q.y)));',
        ' float t=TINT*tin; a=t+(1.-t)*a;',
        ' gl_FragColor=vec4(C*a,a);}'
      ].join('\n');
      function sh(t,src){var s=gl.createShader(t);gl.shaderSource(s,src);gl.compileShader(s);
        if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))console.error(gl.getShaderInfoLog(s));return s;}
      var pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);
      if(!gl.getProgramParameter(pr,gl.LINK_STATUS)) throw new Error('webgl link failed');
      gl.useProgram(pr);
      var b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);
      gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
      var loc=gl.getAttribLocation(pr,'a');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
      var U={};['T','S','D','P','B','TM','IR','C'].forEach(function(n){U[n]=gl.getUniformLocation(pr,n);});
      var tex=gl.createTexture(), ready=false;
      return {
        setImage:function(im){
          gl.bindTexture(gl.TEXTURE_2D,tex);
          gl.texImage2D(gl.TEXTURE_2D,0,gl.LUMINANCE,gl.LUMINANCE,gl.UNSIGNED_BYTE,im);
          gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
          gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
          gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);
          gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
          ready=true;
        },
        draw:function(W,Hh,dpr,p,b,tm,col,ir){
          if(!ready)return;
          gl.viewport(0,0,W,Hh);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);
          gl.uniform1i(U.T,0);gl.uniform2f(U.S,W/dpr,Hh/dpr);gl.uniform1f(U.D,dpr);
          gl.uniform1f(U.P,p);gl.uniform1f(U.B,b);gl.uniform1f(U.TM,tm);gl.uniform1f(U.IR,ir);gl.uniform3f(U.C,col[0],col[1],col[2]);
          gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
        }
      };
    }

    /* ---------- запасной вариант без WebGL ---------- */
    function draw2d(p){
      var W=st.w,Hh=st.h,d=st.dpr,L=lumaData,ar=W/Hh;
      ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,W,Hh);
      ctx.strokeStyle='rgb('+color.map(function(v){return Math.round(v*255);}).join(',')+')';
      var tin=Math.min(1,p/0.12);
      ctx.fillStyle=ctx.strokeStyle; ctx.globalAlpha=TINT*tin; ctx.fillRect(0,0,W,Hh);
      ctx.lineWidth=LINE;
      function rev(y){var f=(p-.12)/.88*(1+BAND);return Math.max(0,Math.min(1,(f-y/Hh)/BAND));}
      function sm(a,b,x){x=Math.max(0,Math.min(1,(x-a)/(b-a)));return x*x*(3-2*x);}
      function sample(x,y){var u=x/W,v=y/Hh;
        if(ar>ratio){v=(v-.5)*(ratio/ar)+.5;}else{u=(u-.5)*(ar/ratio)+.5;}
        var ix=Math.min(L.w-1,Math.max(0,Math.round(u*(L.w-1)))),iy=Math.min(L.h-1,Math.max(0,Math.round(v*(L.h-1))));
        return L.L[iy*L.w+ix];}
      var w=2*Math.PI/CELL, sub=6;
      for(var y=ROW/2;y<Hh+ROW;y+=ROW){
        var ry=rev(y); ctx.globalAlpha=tin*(.3+.7*sm(0,.6,ry));
        ctx.beginPath();ctx.moveTo(0,y);
        for(var cx=0;cx<W;cx+=CELL){
          var dd=Math.pow(1-sample(cx+CELL/2,y),GAMMA);
          var n=(Math.sin((cx/CELL)*127.1+(y/ROW)*311.7)*43758.5453)%1; n=Math.abs(n);
          dd*=sm(0,.7,ry*1.4-(1-dd)*.4-n*.1);
          dd=Math.round(dd*LEVELS)/LEVELS;
          var A=AMIN+(AMAX-AMIN)*dd;
          for(var k=1;k<=sub;k++){var x=cx+CELL*k/sub;ctx.lineTo(x,y+A*Math.sin(x*w));}
        }
        ctx.stroke();
      }
    }
  }
})();
